package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.lwjgl.util.lmdb.LMDB.MDB_MAP_FULL;
import static org.lwjgl.util.lmdb.LMDB.mdb_txn_abort;

import java.io.File;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.file.Path;
import java.util.List;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.XSD;
import org.eclipse.rdf4j.sail.lmdb.TxnManager.Txn;
import org.eclipse.rdf4j.sail.lmdb.config.FrontierEstimatorMode;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.frontier.FrontierMutation;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class TripleStoreMetadataReplayTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI SUBJECT = VF.createIRI("urn:replay:subject");
	private static final IRI PREDICATE = VF.createIRI("urn:replay:predicate");
	private static final Literal CANONICAL = VF.createLiteral("7", XSD.INT);
	private static final Literal NONCANONICAL = VF.createLiteral("007", XSD.INT);

	@Test
	void mapFullReplayCommitsDomainsAndFrontierExactlyOnce(@TempDir Path directory) throws Exception {
		LmdbStoreConfig config = config();
		ValueStore values = new ValueStore(directory.resolve("values").toFile(), config);
		try (ReplayTripleStore store = new ReplayTripleStore(directory.resolve("triples").toFile(), config,
				values)) {
			long[] ids = ids(values);
			seed(store, ids);
			store.startTransaction(trackedDecision());
			assertTrue(store.storeTriple(ids[0], ids[1], ids[3], 0L, true));
			store.recordRdfTermDomain(ids[1], NONCANONICAL);
			store.removeTriplesByContext(ids[0], ids[1], ids[2], 0L, true, row -> {
				try {
					store.recordPredicateObjectRemoval(ids[1], CANONICAL);
				} catch (IOException failure) {
					throw new UncheckedIOException(failure);
				}
			});
			store.failNextCommit(false);
			store.commit();

			assertEquals(1, store.replays);
			assertEquals(1, count(store));
			RdfTermDomain persisted = store.getPersistedRdfTermDomain(ids[1]).orElseThrow();
			assertTrue(persisted.has(RdfTermDomain.Fact.NUMBER));
			assertFalse(persisted.has(RdfTermDomain.Fact.CANONICAL_INTEGER));
			assertEquals(persisted, store.getCachedRdfTermDomain(ids[1]).orElseThrow());
			List<FrontierMutation> mutations = store.readFrontierMutationsAfter(0L, 10);
			assertEquals(List.of(1L, 2L, 3L), mutations.stream().map(FrontierMutation::sequence).toList());
			assertEquals(List.of(true, true, false), mutations.stream().map(FrontierMutation::insertion).toList());
			assertEquals(List.of(ids[2], ids[3], ids[2]), mutations.stream().map(FrontierMutation::objectId).toList());
		} finally {
			values.close();
		}
	}

	@Test
	void failedReplayDiscardsMetadataAndNextWriterReloadsAuthority(@TempDir Path directory) throws Exception {
		LmdbStoreConfig config = config();
		ValueStore values = new ValueStore(directory.resolve("values").toFile(), config);
		try (ReplayTripleStore store = new ReplayTripleStore(directory.resolve("triples").toFile(), config,
				values)) {
			long[] ids = ids(values);
			seed(store, ids);
			store.startTransaction(trackedDecision());
			assertTrue(store.storeTriple(ids[0], ids[1], ids[3], 0L, true));
			store.recordRdfTermDomain(ids[1], NONCANONICAL);
			store.failNextCommit(true);
			IOException failure = assertThrows(IOException.class, store::commit);
			assertEquals("injected metadata replay failure", failure.getMessage());
			assertEquals(1, count(store));
			assertTrue(store.getPersistedRdfTermDomain(ids[1])
					.orElseThrow()
					.has(RdfTermDomain.Fact.CANONICAL_INTEGER));
			assertEquals(1L, store.latestFrontierMutationSequence());

			store.startTransaction(trackedDecision());
			assertTrue(store.storeTriple(ids[4], ids[1], ids[2], 0L, true));
			store.recordRdfTermDomain(ids[1], CANONICAL);
			store.commit();
			assertEquals(2, count(store));
			assertTrue(store.getPersistedRdfTermDomain(ids[1])
					.orElseThrow()
					.has(RdfTermDomain.Fact.CANONICAL_INTEGER));
			assertEquals(List.of(1L, 2L), store.readFrontierMutationsAfter(0L, 10)
					.stream()
					.map(FrontierMutation::sequence)
					.toList());
		} finally {
			values.close();
		}
	}

	private static LmdbStoreConfig config() {
		return new LmdbStoreConfig("spoc,posc").setAutoGrow(true)
				.setTripleDBSize(4L * 1024L * 1024L)
				.setValueDBSize(4L * 1024L * 1024L)
				.setFrontierEstimatorMode(FrontierEstimatorMode.AUTHORITATIVE);
	}

	private static TxnReplayPolicy.Decision trackedDecision() {
		return new TxnReplayPolicy.Decision(null, true, false, 0L, 0L, 0L);
	}

	private static long[] ids(ValueStore values) throws IOException {
		values.startTransaction(true);
		long[] ids = { values.storeValue(SUBJECT), values.storeValue(PREDICATE), values.storeValue(CANONICAL),
				values.storeValue(NONCANONICAL), values.storeValue(VF.createIRI("urn:replay:second")) };
		values.commit();
		return ids;
	}

	private static void seed(ReplayTripleStore store, long[] ids) throws IOException {
		store.startTransaction(trackedDecision());
		assertTrue(store.storeTriple(ids[0], ids[1], ids[2], 0L, true));
		store.recordRdfTermDomain(ids[1], CANONICAL);
		store.commit();
	}

	private static int count(TripleStore store) throws IOException {
		try (Txn txn = store.getTxnManager().createReadTxn();
				RecordIterator records = store.getTriples(txn, -1L, -1L, -1L, -1L, true)) {
			int count = 0;
			while (records.next() != null) {
				count++;
			}
			return count;
		}
	}

	private static final class ReplayTripleStore extends TripleStore {
		private boolean failCommit;
		private boolean failReplay;
		private int replays;

		private ReplayTripleStore(File directory, LmdbStoreConfig config, ValueStore values) throws IOException {
			super(directory, config, values);
		}

		private void failNextCommit(boolean failReplay) {
			failCommit = true;
			this.failReplay = failReplay;
		}

		@Override
		int commitWriteTransaction(long transaction) {
			if (failCommit) {
				failCommit = false;
				mdb_txn_abort(transaction);
				return MDB_MAP_FULL;
			}
			return super.commitWriteTransaction(transaction);
		}

		@Override
		protected void afterMapGrowthReplay() throws IOException {
			replays++;
			if (failReplay) {
				failReplay = false;
				throw new IOException("injected metadata replay failure");
			}
		}
	}
}
